  /// Unique email address used for authentication and account identification.
  email String

  /// BCrypt hashed password for secure authentication credential storage.
  password_hash String

  /// User's public display name shown in the application interface.
  display_name String

  /// Timestamp when the member account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the member account was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the member account was soft deleted. Null indicates active
  /// account.
