    retrieved.start_date,
    todo.start_date,
  );
  TestValidator.equals(
    "todo due_date matches",
    retrieved.due_date,
    todo.due_date,
  );
  TestValidator.equals(
    "todo completed matches",
    retrieved.completed,
    todo.completed,
  );
  TestValidator.equals("todo deleted matches", retrieved.deleted, todo.deleted);
  TestValidator.equals(
