  // 4. Update only completed status - should NOT create edit history entry
  const updatedTodo2 = await api.functional.multiUserTodo.member.todos.update(
    memberConnection,
    {
      todoId: todo.id,
      body: {
        completed: true,
      } satisfies IMultiUserTodoTodo.IUpdate,
    },
  );
