  // 2. Create member with hashed password
  const passwordHash = await PasswordUtil.hash(props.body.password);
  const memberId = v4();
  const member = await MyGlobal.prisma.multi_user_todo_members.create({
    data: {
      id: memberId,
      email: props.body.email,
      password_hash: passwordHash,
      display_name: props.body.display_name,
      created_at: new Date(),
      updated_at: new Date(),
      deleted_at: null,
    },
    ...MultiUserTodoMemberTransformer.select(),
  });
  // 3. Create session
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const sessionId = v4();
  const session = await MyGlobal.prisma.multi_user_todo_member_sessions.create({
    data: {
      id: sessionId,
      multi_user_todo_member_id: member.id,
      ip: props.body.ip ?? props.ip,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: new Date(),
      expired_at: accessExpires,
    },
  });
  // 4. Generate JWT tokens
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        created_at: new Date().toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "member",
        id: member.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: new Date().toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: accessExpires.toISOString(),
    refreshable_until: refreshExpires.toISOString(),
  };
  // 5. Return IAuthorized
  const transformed = await MultiUserTodoMemberTransformer.transform(member);
  return {
    ...transformed,
    token,
  } satisfies IMultiUserTodoMember.IAuthorized;
}

